package jwt.config;import jwt.filter.JwtFilter;import jwt.service.CustomUserDetailsService;import lombok.RequiredArgsConstructor;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import org.springframework.security.authentication.AuthenticationManager;import org.springframework.security.config.annotation.authentication.configuration.AuthenticationConfiguration;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.web.SecurityFilterChain;import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;@Configuration@EnableWebSecurity@RequiredArgsConstructorpublic class SecurityConfig {    private final CustomUserDetailsService userDetailsService;    private final JwtFilter jwtFilter;    @Bean    PasswordEncoder passwordEncoder(){        return new BCryptPasswordEncoder();    }    @Bean    AuthenticationManager authenticationManager(            AuthenticationConfiguration configuration)            throws Exception{        return configuration.getAuthenticationManager();    }    @Bean    SecurityFilterChain filterChain(HttpSecurity http)            throws Exception{        http                .csrf(csrf->csrf.disable())                .authorizeHttpRequests(auth->auth                        .requestMatchers("/login")                        .permitAll()                        .anyRequest()                        .authenticated())                .addFilterBefore(jwtFilter,                        UsernamePasswordAuthenticationFilter.class);        return http.build();    }}